def triangle_area(radius):
    # Calculate the area of the largest triangle that can be inscribed in the semicircle
    return 1/2 * radius * math.sqrt(4 * radius**2 - 4 * radius**2 * math.sin(math.pi/2))

def check_permutation(str1, str2):
    # If the lengths of the strings are different, they cannot be permutations
    if len(str1) != len(str2):
        return False

    # Convert both strings to lowercase to ignore case sensitivity
    str1 = str1.lower()
    str2 = str2.lower()

    # Create a dictionary to count occurrences of each character in str1
    char_count = {}
    for char in str1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Subtract the count of each character in str2 from the dictionary
    for char in str2:
        if char in char_count:
            char_count[char] -= 1
        else:
            char_count[char] = -1

    # If all counts are zero, the strings are permutations of each other
    for count in char_count.values():
        if count != 0:
            return False

    return True
